<script setup lang="ts">
import {ref,computed,useAttrs} from 'vue';defineOptions({inheritAttrs:false});const attrs=useAttrs();const props=defineProps<{modelValue:string;includeTime?:boolean}>();const emit=defineEmits<{ 'update:modelValue':[value:string] }>();const open=ref(false);const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());const month=ref((props.modelValue||today).slice(0,7));const weekdays=['一','二','三','四','五','六','日'];const hours=ref(props.modelValue.slice(11,13)||'00'),minutes=ref(props.modelValue.slice(14,16)||'00');
const caption=computed(()=>month.value.replace('-','年')+'月');const days=computed(()=>{const [y,m]=month.value.split('-').map(Number);const gap=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7;return [...Array(gap).fill(null),...Array.from({length:new Date(Date.UTC(y,m,0)).getUTCDate()},(_,i)=>i+1)];});
function move(delta:number){const [y,m]=month.value.split('-').map(Number);month.value=new Date(Date.UTC(y,m-1+delta,1)).toISOString().slice(0,7);}
function select(value:string){emit('update:modelValue',value+(props.includeTime?'T'+hours.value+':'+minutes.value:''));open.value=false;}
</script>
<template><span class="date-field" @keydown.esc="open=false"><input v-bind="attrs" type="text" :value="modelValue" :placeholder="includeTime?'年-月-日 时:分（北京时间）':'年-月-日'" :aria-label="String(attrs['aria-label']||'日期')" @input="emit('update:modelValue',($event.target as HTMLInputElement).value)"><button type="button" class="date-toggle" @click="open=!open" :aria-expanded="open" aria-label="打开中文日期选择器">选日期</button><section v-if="open" class="date-popup" role="dialog" aria-label="中文日期选择器"><header><button type="button" @click="move(-1)" aria-label="上个月">‹</button><strong>{{caption}}</strong><button type="button" @click="move(1)" aria-label="下个月">›</button></header><div class="date-grid"><span v-for="name in weekdays" :key="name">周{{name}}</span><template v-for="(day,i) in days" :key="i"><button v-if="day" type="button" @click="select(month+'-'+String(day).padStart(2,'0'))" :aria-label="caption+day+'日'">{{day}}</button><span v-else/></template></div><label v-if="includeTime">北京时间 <select v-model="hours" aria-label="小时"><option v-for="n in 24" :value="String(n-1).padStart(2,'0')">{{n-1}}时</option></select><select v-model="minutes" aria-label="分钟"><option v-for="n in 60" :value="String(n-1).padStart(2,'0')">{{n-1}}分</option></select></label><footer><button type="button" @click="select(today)">今天</button><button type="button" @click="emit('update:modelValue','');open=false">清空</button><button type="button" @click="open=false">关闭</button></footer></section></span></template>
<style scoped>.date-field{position:relative;display:flex;gap:4px;min-width:0;max-width:100%}.date-field input{width:170px;min-width:0}.date-toggle{padding:5px 8px;white-space:nowrap}.date-popup{position:absolute;z-index:30;top:100%;left:0;width:min(330px,calc(100vw - 42px));background:#101b2d;border:1px solid #59728f;border-radius:10px;padding:12px;box-shadow:0 10px 32px #0008}.date-popup header{margin:0 0 10px;display:flex;align-items:center;justify-content:space-between}.date-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:2px}.date-grid span{font-size:13px;text-align:center;color:#b9c9dd}.date-grid button{padding:2px;min-width:0;margin:0;font-size:14px}.date-popup footer{gap:4px;flex-wrap:wrap;padding-top:10px}.date-popup footer button{padding:5px 10px}@media(max-width:650px){.date-field{width:100%}.date-field input{flex:1;width:0}}</style>
